static int tr_find_14(uint32_t letter) {
    for(unsigned i = 0; i < sizeof(tr_glyphs_14) / sizeof(tr_glyphs_14[0]); ++i)
        if(tr_glyphs_14[i].codepoint == letter) return (int)i;
    return -1;
}

static bool tr_get_dsc_14(const lv_font_t *font, lv_font_glyph_dsc_t *d, uint32_t letter, uint32_t next) {
    (void)font; (void)next;
    int idx = tr_find_14(letter);
    if(idx < 0) return false;
    const tr_glyph_dsc_14_t *g = &tr_glyphs_14[idx];
    d->adv_w = g->adv_w; d->box_w = g->box_w; d->box_h = g->box_h;
    d->ofs_x = g->ofs_x; d->ofs_y = g->ofs_y; d->format = LV_FONT_GLYPH_FORMAT_A8;
    d->is_placeholder = 0; d->glyph_index = (uint32_t)idx; d->entry = NULL;
    return true;
}

static const void *tr_get_bitmap_14(lv_font_glyph_dsc_t *d, uint32_t letter, lv_draw_buf_t *buf) {
    (void)letter;
    if(!buf || !buf->data) return NULL;
    uint32_t idx = d->glyph_index;
    if(idx >= sizeof(tr_glyphs_14) / sizeof(tr_glyphs_14[0])) return NULL;
    const tr_glyph_dsc_14_t *g = &tr_glyphs_14[idx];
    const uint8_t *src = &tr_bitmap_14[g->bitmap_index];
    for(uint32_t y = 0; y < g->box_h; ++y)
        memcpy((uint8_t *)buf->data + y * buf->header.stride, src + y * g->box_w, g->box_w);
    return buf;
}

